lpml.css:
#langpedia {
    animation: growrotate 1.5s ease-in-out infinite alternate;
    color: lightblue;
}

@keyframes growrotate {
    from {
        transform: scale(1) rotate(-4deg);
    }
    to {
        transform: scale(1.1) rotate(10deg);
    }
}

body {
    overflow-x: hidden;
}

lpml.JS:
const articles = {{ARTICLES_ARRAY}};
const searchinput = document.getElementById("searchinput");

searchinput.addEventListener('keydown', function(event) {
    if (event.key == "Enter") {
        var article = articles.filter(a => a.includes(searchinput.value.toLowerCase()))[0];
        window.location.href = "{{ROOT}}" + article + ".html";
    }
});
